using System;
using System.Collections;
using System.Collections.Generic;
using FMODUnity;
using LittleLeo;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "GainDiceAction", menuName = "Data/Battle/Battle Actions/Enemy/Hex Action")]
public class HexAction : BattleAction
{
	[Header("Player Dice Pool")]
	[SerializeField]
	private PlayerDiceInventoryData targetPlayerDicePool;

	[SerializeField]
	private bool bag = true;

	[Header("Dice")]
	[SerializeField]
	[ShowIf("isScriptableDie")]
	private Dice dice;

	[SerializeField]
	[HideIf("runtimeDie")]
	private bool enableDiceName;

	[SerializeField]
	[ShowIf("isEnableDiceName")]
	private string diceName;

	[SerializeField]
	private bool runtimeDie;

	[Header("Receive Dice Prefab")]
	[SerializeField]
	private GameObject receiveDiceAnimationPrefab;

	[Header("Dice Discovered System")]
	[SerializeField]
	private DicesRewardsListsList dicesRewardsListsList;

	[Header("Description")]
	[SerializeField]
	private bool useDiceOfForDescription;

	[SerializeField]
	[HideIf("useDiceOfForDescription")]
	private Tag tagHexDie;

	[Header("SFX")]
	[SerializeField]
	private EventReference hexSFX;

	public bool Bag => bag;

	public string DiceName => diceName;

	private bool isEnableDiceName
	{
		get
		{
			if (enableDiceName)
			{
				return !runtimeDie;
			}
			return false;
		}
	}

	private bool isScriptableDie
	{
		get
		{
			if (!enableDiceName)
			{
				return !runtimeDie;
			}
			return false;
		}
	}

	public bool UseDiceOfForDescription => useDiceOfForDescription;

	public Tag TagHexDie => tagHexDie;

	public override void Cast(GameObject source)
	{
		CastAction(GainDiceAnimationMultipleTimes(1, source));
	}

	public override void CastAmount(int amount, GameObject source)
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.WickedsCardOmenAction?.Invoke(source, ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject);
		ReferenceSingleton<MiscOmensHandler>.Instance.ResetWickedsCardOmenAction?.Invoke(source);
		CastAction(GainDiceAnimationMultipleTimes(amount, source));
	}

	public void CastAmountAction(int amount, GameObject source, Action afterGainDiceAnimation, bool dontEnterChooseActionState)
	{
		CastAction(GainDiceAnimationMultipleTimes(amount, source, afterGainDiceAnimation), dontEnterChooseActionState);
	}

	public void CastWithRuntimeDie(GameObject source, Dice runtimeDie)
	{
		CastAction(GainDiceAnimationMultipleTimes(1, source, null, runtimeDie));
	}

	private void CastAction(IEnumerator gainDiceAnimation, bool dontEnterChooseActionState = false)
	{
		ReferenceSingleton<GameStateManager>.Instance.TryEnterNoInteractionState();
		ReferenceSingleton<CoroutineHandler>.Instance.Run(gainDiceAnimation);
		if (!dontEnterChooseActionState)
		{
			ReferenceSingleton<GameStateManager>.Instance.TryEnterChooseActionState(WaitForFramesType.WaitToUpdateCorruptionFrames);
		}
	}

	private IEnumerator GainDiceAnimationMultipleTimes(int amount, GameObject source, Action afterGainDiceAnimation = null, Dice runtimeDie = null)
	{
		PlayerDice playerDice = (enableDiceName ? (ReferenceSingleton<AssetsReference>.Instance.AllPlayerDicesList.GetDice(diceName) as PlayerDice) : ((!(runtimeDie != null)) ? (dice as PlayerDice) : (runtimeDie as PlayerDice)));
		if (playerDice.CompendiumItemState == CompendiumItemState.Undiscovered)
		{
			List<Dice> list = new List<Dice>();
			list.Add(playerDice);
			dicesRewardsListsList.DiceDiscovered(list, dontGetOtherTiersDiscover: true);
		}
		targetPlayerDicePool.IncreaseDiceAmount(playerDice, amount, insertAsFirst: false, updateDicePoolText: false);
		for (int i = 0; i < amount; i++)
		{
			GainDiceAnimation(source, playerDice);
			if (i == amount - 1)
			{
				yield return new WaitForSeconds(0.55f);
			}
			else
			{
				yield return new WaitForSeconds(0.15f);
			}
		}
		afterGainDiceAnimation?.Invoke();
	}

	private void GainDiceAnimation(GameObject source, Dice diceToGain)
	{
		ReferenceSingleton<SFXHandler>.Instance.PlaySFX(hexSFX);
		if (source == null)
		{
			source = ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject;
		}
		ReceiveDiceAnimation component = ReferenceSingleton<PoolHandler>.Instance.GetObject(receiveDiceAnimationPrefab.name, source.transform.position).GetComponent<ReceiveDiceAnimation>();
		component.Initialize(dice: diceToGain.InstantiateScriptableObjectTryingToCopyDiceFacesModded(), bagEnum: bag ? BagEnum.DrawPool : BagEnum.Discard, playerDiceInventoryData: targetPlayerDicePool);
		component.StartAnimation();
	}
}
